CREATE     PROCEDURE [synapse_fo].[usp_Update_CUSTSETTLEMENT]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:30:34
	Description: Update stored procedure for CUSTSETTLEMENT from synapse finops datalake to BI
*/
BEGIN
	UPDATE tgt SET 
		tgt.[ACCOUNTNUM] = stg.[ACCOUNTNUM],
		tgt.[CANBEREVERSED] = stg.[CANBEREVERSED],
		tgt.[CASHDISCOUNTLEDGERDIMENSION] = stg.[CASHDISCOUNTLEDGERDIMENSION],
		tgt.[CLOSEDDATE] = stg.[CLOSEDDATE],
		tgt.[CREATEDBY] = stg.[CREATEDBY],
		tgt.[CREATEDDATETIME] = stg.[CREATEDDATETIME],
		tgt.[CUSTCASHDISCDATE] = stg.[CUSTCASHDISCDATE],
		tgt.[DATAAREAID] = stg.[DATAAREAID],
		tgt.[DataLakeModified_DateTime] = stg.[DataLakeModified_DateTime],
		tgt.[DEFAULTDIMENSION] = stg.[DEFAULTDIMENSION],
		tgt.[DUEDATE] = stg.[DUEDATE],
		tgt.[EUSALESLIST] = stg.[EUSALESLIST],
		tgt.[EXCHADJUSTMENT] = stg.[EXCHADJUSTMENT],
		tgt.[EXCHADJUSTMENTREPORTING] = stg.[EXCHADJUSTMENTREPORTING],
		--tgt.[FileName] = stg.[FileName],
		tgt.[FINEAMOUNT_BR] = stg.[FINEAMOUNT_BR],
		tgt.[FINECODE_BR] = stg.[FINECODE_BR],
		tgt.[INTERESTAMOUNT_BR] = stg.[INTERESTAMOUNT_BR],
		tgt.[INTERESTCODE_BR] = stg.[INTERESTCODE_BR],
		tgt.[LASTINTERESTDATE] = stg.[LASTINTERESTDATE],
		tgt.[LastProcessedChange_DateTime] = stg.[LastProcessedChange_DateTime],
		--tgt.[LSN] = stg.[LSN],
		tgt.[OFFSETACCOUNTNUM] = stg.[OFFSETACCOUNTNUM],
		tgt.[OFFSETCOMPANY] = stg.[OFFSETCOMPANY],
		tgt.[OFFSETRECID] = stg.[OFFSETRECID],
		tgt.[OFFSETTRANSVOUCHER] = stg.[OFFSETTRANSVOUCHER],
		tgt.[PARTITION] = stg.[PARTITION],
		tgt.[PENNYDIFF] = stg.[PENNYDIFF],
		tgt.[RECID] = stg.[RECID],
		tgt.[RECVERSION] = stg.[RECVERSION],
		tgt.[REPORTINGDATE_RU] = stg.[REPORTINGDATE_RU],
		tgt.[REVERSEDRECID_RU] = stg.[REVERSEDRECID_RU],
		tgt.[REVERSETRANS_RU] = stg.[REVERSETRANS_RU],
		tgt.[SETTLEAMOUNTCUR] = stg.[SETTLEAMOUNTCUR],
		tgt.[SETTLEAMOUNTMST] = stg.[SETTLEAMOUNTMST],
		tgt.[SETTLEAMOUNTREPORTING] = stg.[SETTLEAMOUNTREPORTING],
		tgt.[SETTLEMENTGROUP] = stg.[SETTLEMENTGROUP],
		tgt.[SETTLEMENTVOUCHER] = stg.[SETTLEMENTVOUCHER],
		tgt.[SETTLETAX1099AMOUNT] = stg.[SETTLETAX1099AMOUNT],
		tgt.[SETTLETAX1099STATEAMOUNT] = stg.[SETTLETAX1099STATEAMOUNT],
		--tgt.[SKS_EPY_TRANSOPENRECID] = stg.[SKS_EPY_TRANSOPENRECID],
		--tgt.[SysRowId] = stg.[SysRowId],
		tgt.[TAXVOUCHER_RU] = stg.[TAXVOUCHER_RU],
		tgt.[TRANSCOMPANY] = stg.[TRANSCOMPANY],
		tgt.[TRANSDATE] = stg.[TRANSDATE],
		tgt.[TRANSOPEN] = stg.[TRANSOPEN],
		tgt.[TRANSRECID] = stg.[TRANSRECID],
		tgt.[TRANSTYPE] = stg.[TRANSTYPE],
		tgt.[UTILIZEDCASHDISC] = stg.[UTILIZEDCASHDISC]
	 FROM [synapse_fo].[CUSTSETTLEMENT] tgt
		INNER JOIN [staging_fo].[CUSTSETTLEMENT] stg
			ON  stg.[RECID] = tgt.[RECID] 
		
END
